/**
 * Purges IP addresses from the afl_ip and afl_ip_hex columns if the row was created more than
 * a specified number of days ago.
 *
 * @param int $days Number of days to check for rows to purge
 */
public function purgeOldIPs(int $days): void {
    $dbr = $this->getConnectionProvider()->getReadConnection();
    $cutoff = $dbr->timestampAdd($dbr->now(), "-$days days");

    $dbr->delete(
        'archive',
        [
            'afl_timestamp < ' . $dbr->quote($cutoff),
            'afl_ip != ""',
            'afl_ip_hex != ""'
        ],
        __METHOD__
    );

    $this->getHookRunner()->onArchivePurgeOldIPs($days);
}
