/**
 * Fetch the size of the lead section of a given Wikipedia article (in characters of wikitext).
 *
 * @param string $title The title of the Wikipedia article.
 * @return int The size of the lead section in characters.
 */
public function getLeadSectionSize(string $title): int {
    $page = WikiPage::factory(Title::newFromText($title));
    $content = $page->getContent();
    if ($content instanceof TextContent) {
        $text = $content->getText();
        $sections = Section::newFromText($text);
        if ($sections && $sections->hasSection(0)) {
            return mb_strlen($sections->getSection(0)->getText());
        }
    }
    return 0;
}
